package io.github.pennstatecs.geokit.datum

import io.github.pennstatecs.geokit.ellipsoid.Ellipsoid
import io.github.pennstatecs.geokit.ellipsoid.GeodeticPosition
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertSame
import org.junit.Assert.assertTrue
import org.junit.Test
import kotlin.math.abs
import kotlin.math.cos
import kotlin.math.hypot

/**
 * Frames, epochs and the transformation registry, against PROJ 9.8.1 reference vectors
 * (`coords/itrf2020_vectors.csv`, generated by tools/coords/gen_itrf2020_vectors.py):
 * EPSG "ITRF2014 to ITRF2020 (1)" both ways, and PROJ's direct "ITRF2020 to NAD83(2011) (1)" against
 * GeoKit's chain ITRF2020 → ITRF2014 → NAD83(2011).
 */
class FrameTransformationRegistryTest {

    private val registry = FrameTransformationRegistry.DEFAULT
    private val e2026 = CoordinateEpoch(2026.9)

    private data class Vector(val op: String, val src: GeodeticPosition, val epoch: Double, val expected: GeodeticPosition)

    private val vectors: List<Vector> by lazy {
        val text = requireNotNull(javaClass.getResourceAsStream("/coords/itrf2020_vectors.csv")) { "missing vectors" }
            .bufferedReader().readText()
        text.lineSequence().filter { it.isNotBlank() && !it.startsWith("#") && !it.startsWith("op,") }.map { l ->
            val f = l.split(',')
            Vector(f[0], GeodeticPosition(f[1].toDouble(), f[2].toDouble(), f[3].toDouble()), f[4].toDouble(),
                GeodeticPosition(f[5].toDouble(), f[6].toDouble(), f[7].toDouble()))
        }.toList()
    }

    /** Horizontal distance in metres between two nearby positions (local approximation, fine at mm level). */
    private fun horizontalM(a: GeodeticPosition, b: GeodeticPosition): Double {
        val r = Ellipsoid.GRS80
        var dLon = a.lonDeg - b.lonDeg
        if (dLon > 180) dLon -= 360.0
        if (dLon < -180) dLon += 360.0
        val dn = Math.toRadians(a.latDeg - b.latDeg) * r.meridianRadiusM(a.latDeg)
        val de = Math.toRadians(dLon) * r.primeVerticalRadiusM(a.latDeg) * cos(Math.toRadians(a.latDeg))
        return hypot(dn, de)
    }

    private fun available(s: ReferenceFrame, t: ReferenceFrame, epoch: CoordinateEpoch = e2026) =
        registry.find(s, t, epoch) as FrameTransformationLookup.Available

    private fun checkVectors(op: String, s: ReferenceFrame, t: ReferenceFrame, expectedSteps: Int) {
        val rows = vectors.filter { it.op == op }
        assertEquals(op, 76, rows.size)   // 19 points × 4 epochs
        var worstH = 0.0; var worstV = 0.0
        for (v in rows) {
            val lookup = available(s, t, CoordinateEpoch(v.epoch))
            assertEquals(expectedSteps, lookup.transformation.steps.size)
            val out = lookup.apply(v.src)
            worstH = maxOf(worstH, horizontalM(out, v.expected))
            worstV = maxOf(worstV, abs(out.heightM - v.expected.heightM))
        }
        println("$op: ${rows.size} vectors, worst horizontal ${"%.3e".format(worstH)} m, vertical ${"%.3e".format(worstV)} m")
        // ≤ 0.1 mm horizontal and vertical (PROJ output is rounded to ~0.1 µm / 1 µm).
        assertTrue("$op worst horizontal ${worstH * 1000} mm", worstH < 1e-4)
        assertTrue("$op worst vertical ${worstV * 1000} mm", worstV < 1e-4)
    }

    // ── Frames and epochs ───────────────────────────────────────────────────────────────────────

    @Test fun `frame ids are stable and unique`() {
        val expected = mapOf(
            ReferenceFrame.ITRF2014 to "itrf2014", ReferenceFrame.ITRF2020 to "itrf2020",
            ReferenceFrame.WGS84_AS_ITRF2014 to "wgs84-as-itrf2014", ReferenceFrame.WGS84 to "wgs84",
            ReferenceFrame.WGS84_G1762 to "wgs84-g1762", ReferenceFrame.WGS84_G2139 to "wgs84-g2139",
            ReferenceFrame.WGS84_G2296 to "wgs84-g2296", ReferenceFrame.NAD83_2011 to "nad83-2011",
            ReferenceFrame.NATRF2022 to "natrf2022",
        )
        assertEquals(expected.keys, ReferenceFrame.entries.toSet())
        for ((f, id) in expected) { assertEquals(id, f.id); assertSame(f, ReferenceFrame.fromId(id)) }
        assertNull(ReferenceFrame.fromId("itrf2025")); assertNull(ReferenceFrame.fromId(null)); assertNull(ReferenceFrame.fromId("ITRF2014"))
    }

    @Test fun `frame metadata matches EPSG`() {
        with(ReferenceFrame.ITRF2020) {
            assertEquals(9988, epsgGeocentric); assertEquals(9989, epsg3d); assertEquals(9990, epsg2d)
            assertEquals(2015.0, referenceEpoch!!, 0.0); assertEquals(FrameKind.GLOBAL, kind); assertSame(Ellipsoid.GRS80, ellipsoid)
        }
        with(ReferenceFrame.ITRF2014) { assertEquals(7912, epsg3d); assertEquals(2010.0, referenceEpoch!!, 0.0) }
        with(ReferenceFrame.NATRF2022) {
            assertEquals(10966, epsgGeocentric); assertEquals(10967, epsg3d); assertEquals(10968, epsg2d)
            assertEquals(FrameKind.PLATE_FIXED, kind)
        }
        with(ReferenceFrame.NAD83_2011) { assertEquals(6319, epsg3d); assertEquals(FrameKind.PLATE_FIXED, kind) }
        assertEquals(4979, ReferenceFrame.WGS84_AS_ITRF2014.epsg3d)
        assertSame(ReferenceFrame.ITRF2014, ReferenceFrame.WGS84_AS_ITRF2014.coordinatesFrame)
        assertSame(ReferenceFrame.WGS84, ReferenceFrame.WGS84.coordinatesFrame)
        assertEquals(10605, ReferenceFrame.WGS84_G2296.epsg3d); assertEquals(9754, ReferenceFrame.WGS84_G2139.epsg3d)
    }

    @Test fun `coordinate epoch`() {
        assertEquals(2026.0, CoordinateEpoch.fromEpochMillis(java.time.Instant.parse("2026-01-01T00:00:00Z").toEpochMilli()).decimalYear, 1e-12)
        val ms = java.time.Instant.parse("2026-11-20T04:00:00Z").toEpochMilli()
        assertEquals(Itrf2014ToNad83.decimalYear(ms), CoordinateEpoch.fromEpochMillis(ms).decimalYear, 0.0)
        for (bad in listOf(Double.NaN, Double.POSITIVE_INFINITY)) {
            assertTrue(runCatching { CoordinateEpoch(bad) }.exceptionOrNull() is IllegalArgumentException)
        }
    }

    // ── PROJ vectors ────────────────────────────────────────────────────────────────────────────

    @Test fun `ITRF2014 to ITRF2020 matches PROJ`() = checkVectors("itrf2014_to_itrf2020", ReferenceFrame.ITRF2014, ReferenceFrame.ITRF2020, 1)

    @Test fun `ITRF2020 to ITRF2014 matches PROJ`() = checkVectors("itrf2020_to_itrf2014", ReferenceFrame.ITRF2020, ReferenceFrame.ITRF2014, 1)

    @Test fun `WGS84 (ITRF2014) alias to ITRF2020 is the ITRF2014 edge`() =
        checkVectors("itrf2014_to_itrf2020", ReferenceFrame.WGS84_AS_ITRF2014, ReferenceFrame.ITRF2020, 1)

    @Test fun `ITRF2020 to NAD83(2011) chain matches PROJ's direct EPSG operation`() =
        checkVectors("itrf2020_to_nad83_2011", ReferenceFrame.ITRF2020, ReferenceFrame.NAD83_2011, 2)

    @Test fun `round trips stay below 0_1 mm`() {
        val pairs = listOf(
            ReferenceFrame.ITRF2014 to ReferenceFrame.ITRF2020,
            ReferenceFrame.ITRF2020 to ReferenceFrame.NAD83_2011,
            ReferenceFrame.WGS84_AS_ITRF2014 to ReferenceFrame.NAD83_2011,
        )
        for (v in vectors.filter { it.op == "itrf2014_to_itrf2020" }) for ((s, t) in pairs) {
            val epoch = CoordinateEpoch(v.epoch)
            val back = available(t, s, epoch).apply(available(s, t, epoch).apply(v.src))
            assertTrue("$s⇄$t ${v.src}", horizontalM(back, v.src) < 1e-4)
            assertEquals(v.src.heightM, back.heightM, 1e-4)
        }
    }

    @Test fun `ITRF2014 to ITRF2020 depends on the epoch as the rates say`() {
        val p = GeodeticPosition(0.0, 90.0, 0.0)   // ECEF Y axis: dY/dt = +0.1 mm/yr appears as height
        val a = available(ReferenceFrame.ITRF2014, ReferenceFrame.ITRF2020, CoordinateEpoch(2015.0)).apply(p)
        val b = available(ReferenceFrame.ITRF2014, ReferenceFrame.ITRF2020, CoordinateEpoch(2025.0)).apply(p)
        assertEquals(0.001, b.heightM - a.heightM, 1e-6)          // 10 yr × 0.1 mm/yr
        val pole = GeodeticPosition(90.0, 0.0, 0.0)  // Z axis: dZ/dt = −0.2 mm/yr
        val c = available(ReferenceFrame.ITRF2014, ReferenceFrame.ITRF2020, CoordinateEpoch(2015.0)).apply(pole)
        val d = available(ReferenceFrame.ITRF2014, ReferenceFrame.ITRF2020, CoordinateEpoch(2025.0)).apply(pole)
        assertEquals(-0.002, d.heightM - c.heightM, 1e-6)
        // At t0 the shift is T + D·r: Tz − 1.4 mm plus scale 0.42 ppb × polar radius (≈ 2.67 mm).
        assertEquals(-0.0014 + 0.42e-9 * Ellipsoid.GRS80.semiMinorAxisM, c.heightM, 1e-6)
    }

    // ── Registry ────────────────────────────────────────────────────────────────────────────────

    @Test fun `ITRF2014 to NAD83(2011) delegates to the existing Helmert bit for bit`() {
        val p = GeodeticPosition(41.3477, -76.0226, 390.0)
        for (epoch in listOf(2010.0, 2026.886)) {
            val f = available(ReferenceFrame.ITRF2014, ReferenceFrame.NAD83_2011, CoordinateEpoch(epoch)).apply(p)
            assertEquals(Itrf2014ToNad83.forward(p, epoch), f)
            val r = available(ReferenceFrame.NAD83_2011, ReferenceFrame.WGS84_AS_ITRF2014, CoordinateEpoch(epoch)).apply(p)
            assertEquals(Itrf2014ToNad83.inverse(p, epoch), r)
        }
    }

    @Test fun `same frame and alias need no transformation`() {
        val p = GeodeticPosition(41.0, -76.0, 300.0)
        for ((s, t) in listOf(ReferenceFrame.ITRF2020 to ReferenceFrame.ITRF2020,
                              ReferenceFrame.ITRF2014 to ReferenceFrame.WGS84_AS_ITRF2014,
                              ReferenceFrame.WGS84_AS_ITRF2014 to ReferenceFrame.ITRF2014)) {
            val l = available(s, t)
            assertTrue(l.transformation.steps.isEmpty())
            assertSame(p, l.apply(p))
        }
    }

    @Test fun `chains are built only from registered edges`() {
        val l = available(ReferenceFrame.ITRF2020, ReferenceFrame.NAD83_2011)
        assertEquals(listOf(FrameTransformationRegistry.ITRF2014_TO_ITRF2020, FrameTransformationRegistry.ITRF2014_TO_NAD83_2011),
            l.transformation.steps)
        assertEquals("ITRF2020 → ITRF2014 → NAD83(2011)", l.transformation.description)
        assertEquals("NAD83(2011) → ITRF2014 → ITRF2020", available(ReferenceFrame.NAD83_2011, ReferenceFrame.ITRF2020).transformation.description)
        assertEquals("WGS84 (ITRF2014) → ITRF2020", available(ReferenceFrame.WGS84_AS_ITRF2014, ReferenceFrame.ITRF2020).transformation.description)
        // Without the ITRF2020 edge, ITRF2020 is not connected.
        val small = FrameTransformationRegistry(listOf(FrameTransformationRegistry.ITRF2014_TO_NAD83_2011))
        val u = small.find(ReferenceFrame.ITRF2020, ReferenceFrame.NAD83_2011, e2026) as FrameTransformationLookup.Unavailable
        assertEquals(FrameUnavailableReason.NOT_DEFINED, u.reason)
    }

    @Test fun `NATRF2022 is never available`() {
        for (other in ReferenceFrame.entries.filter { it != ReferenceFrame.NATRF2022 }) {
            for ((s, t) in listOf(other to ReferenceFrame.NATRF2022, ReferenceFrame.NATRF2022 to other)) {
                val u = registry.find(s, t, e2026)
                assertTrue("$s → $t", u is FrameTransformationLookup.Unavailable)
                u as FrameTransformationLookup.Unavailable
                if (other in FrameTransformationRegistry.DEFAULT_UNAVAILABLE) continue
                assertEquals(FrameUnavailableReason.NOT_VERIFIED, u.reason)
                assertTrue(u.explanation, u.explanation.contains("NATRF2022") && u.explanation.contains("ballpark"))
            }
        }
        // Even a registry with an edge into NATRF2022 refuses it while the frame is listed as unavailable.
        val bogus = FrameEdge(ReferenceFrame.ITRF2020, ReferenceFrame.NATRF2022, "bogus", null, "none", { p, _ -> p }, { p, _ -> p })
        val r = FrameTransformationRegistry(listOf(FrameTransformationRegistry.ITRF2014_TO_ITRF2020, bogus),
            FrameTransformationRegistry.DEFAULT_UNAVAILABLE)
        assertTrue(r.find(ReferenceFrame.ITRF2014, ReferenceFrame.NATRF2022, e2026) is FrameTransformationLookup.Unavailable)
    }

    @Test fun `WGS84 ensemble and realisations are not treated as ITRF`() {
        for (w in listOf(ReferenceFrame.WGS84, ReferenceFrame.WGS84_G1762, ReferenceFrame.WGS84_G2139, ReferenceFrame.WGS84_G2296))
            for (t in listOf(ReferenceFrame.ITRF2014, ReferenceFrame.ITRF2020, ReferenceFrame.NAD83_2011, ReferenceFrame.WGS84_AS_ITRF2014)) {
                val u = registry.find(w, t, e2026) as FrameTransformationLookup.Unavailable
                assertEquals(FrameUnavailableReason.NOT_VERIFIED, u.reason)
                assertFalse(u.explanation.isBlank())
            }
    }

    @Test fun `lookup by id`() {
        val a = registry.find("itrf2020", "nad83-2011", e2026)
        assertTrue(a is FrameTransformationLookup.Available)
        for ((s, t) in listOf("itrf2025" to "itrf2020", "itrf2020" to "", "WGS84" to "nad83-2011")) {
            val u = registry.find(s, t, e2026) as FrameTransformationLookup.Unavailable
            assertEquals(FrameUnavailableReason.UNKNOWN_FRAME, u.reason)
            assertEquals(s, u.source); assertEquals(t, u.target)
        }
        val n = registry.find("natrf2022", "itrf2020", e2026) as FrameTransformationLookup.Unavailable
        assertEquals(FrameUnavailableReason.NOT_VERIFIED, n.reason)
    }

    @Test fun `edges must join two different coordinate frames`() {
        val id: (GeodeticPosition, Double) -> GeodeticPosition = { p, _ -> p }
        assertTrue(runCatching { FrameEdge(ReferenceFrame.WGS84_AS_ITRF2014, ReferenceFrame.ITRF2020, "x", null, "", id, id) }
            .exceptionOrNull() is IllegalArgumentException)
        assertTrue(runCatching { FrameEdge(ReferenceFrame.ITRF2020, ReferenceFrame.ITRF2020, "x", null, "", id, id) }
            .exceptionOrNull() is IllegalArgumentException)
    }
}
